import{c as o,$ as n,Q as d,j as c,g as e,o as h,n as l,m as r,a4 as s}from"./chunks/framework.Ce_49mA8.js";const m=JSON.parse('{"title":"Модуль «Амбассадор»","description":"Практическое руководство по сквозному модулю «Амбассадор»: продвижение собственного дела, генерация целевых ссылок, QR-коды на чеках, учет кампаний и партнерская программа.","frontmatter":{"title":"Модуль «Амбассадор»","description":"Практическое руководство по сквозному модулю «Амбассадор»: продвижение собственного дела, генерация целевых ссылок, QR-коды на чеках, учет кампаний и партнерская программа.","datePublished":"2026-10-28","dateModified":"2026-11-16","order":22},"headers":[],"relativePath":"ru/docs/spaces/ambassador.md","filePath":"ru/docs/spaces/ambassador.md","lastUpdated":1794787200000}'),g={name:"ru/docs/spaces/ambassador.md"},p={id:"модуль-«амбассадор»-продвижение-своего-дела-и-партнерская-экосистема",tabindex:"-1"};function u(a,t,f,x,b,v){const i=n("DocIcon");return d(),c("div",null,[e("h1",p,[h(i,{name:"ambassador"}),t[0]||(t[0]=l(" Модуль «Амбассадор»: Продвижение своего дела и партнерская экосистема ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#модуль-«амбассадор»-продвижение-своего-дела-и-партнерская-экосистема","aria-label":'Permalink to "Модуль «Амбассадор»: Продвижение своего дела и партнерская экосистема"'},"​",-1))]),t[5]||(t[5]=r('<p>Каждый мастер, создающий качественные изделия или оказывающий надежные сервисные услуги, неизбежно сталкивается с задачей привлечения клиентов. Одни публикуют мастер-классы и советы на тематических форумах, другие ведут сообщества в социальных сетях, третьи заказывают платную рекламу или договариваются о совместных проектах с коллегами.</p><p>В большинстве программ для малого бизнеса маркетинг либо отсутствует вовсе, либо сводится к громоздким и дорогим внешним системам. В ОмниКрафт ЕРП этот контур реализован как бесплатный встроенный инструмент — <strong>модуль «Амбассадор»</strong>.</p><p>Инструмент решает две ключевые задачи практикующего предпринимателя:</p><ul><li><strong>Продвижение собственной мастерской:</strong> структурированный поиск целевых площадок, ведение рекламных кампаний, генерация точных ссылок с метками, составление публикаций с помощью искусственного интеллекта и наглядный расчет окупаемости расходов;</li><li><strong>Партнерский доход в экосистеме ОмниКрафт ЕРП:</strong> рекомендация программы коллегам по ремеслу с начислением бессрочного вознаграждения в рублях (до 50% с каждой оплаты привлеченного пользователя) с возможностью вывода средств на банковский счет или оплаты лицензий прямо из баланса.</li></ul><hr><h2 id="архитектура-инструмента-двоинои-режим-и-изоляция-данных" tabindex="-1">Архитектура инструмента: двойной режим и изоляция данных <a class="header-anchor" href="#архитектура-инструмента-двоинои-режим-и-изоляция-данных" aria-label="Permalink to &quot;Архитектура инструмента: двойной режим и изоляция данных&quot;">​</a></h2><p>Модуль спроектирован по принципу максимальной автономии и бережного отношения к ресурсам компьютера:</p><div class="craft-window-frame" data-title="Модуль «Амбассадор»"><div style="padding:1rem 1.25rem;"><table class="craft-matrix-table" style="margin:0;text-align:center;"><thead><tr><th style="width:20%;text-align:center;">Кабинет</th><th style="width:20%;text-align:center;">Источники</th><th style="width:20%;text-align:center;">Кампании</th><th style="width:20%;text-align:center;">Аналитика</th><th style="width:20%;text-align:center;">Настройки</th></tr></thead><tbody><tr><td>Партнёрский баланс, статус и прогресс ранга</td><td>Каталог площадок и библиотека аудиторий</td><td>Управление кампаниями и тексты публикаций</td><td>Воронка конверсий и финансовые метрики</td><td>Управление доменами и интеграциями</td></tr></tbody></table></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Двойной режим запуска:</strong> модуль работает как полноправный раздел внутри основного интерфейса ОмниКрафт ЕРП (с единой панелью команд в стиле раздела «Мой капитал»), а также может запускаться как полностью автономное независимое приложение <code>Ambassador.exe</code>.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></span><span><strong>Сквозная сохранность базы данных:</strong> все созданные ссылки, карточки площадок, тексты публикаций и статистика хранятся в защищенном системном файле <code>global_extensions.db</code>. Если вы решите переформатировать мастерскую, сбросить операционную историю кассы или заархивировать производство, данные модуля останутся в абсолютной сохранности.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg></span><span><strong>Устойчивость к отсутствию сети:</strong> генерация ссылок, ведение базы контактов и анализ локальных данных работают на 100% автономно. При временном отсутствии интернета программа моментально отображает последние сохраненные показатели без подвисаний.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Прямой доступ через меню</p><p>Открыть модуль можно в любой момент из главного меню программы или через боковую панель в блоке «Сквозные модули». Модуль доступен бесплатно на всех коммерческих тарифах программы.</p></div><hr><h2 id="_1-вкладка-«кабинет»-профиль-быстрые-ссылки-и-центр-ссылок" tabindex="-1">1. Вкладка «Кабинет»: Профиль, быстрые ссылки и центр ссылок <a class="header-anchor" href="#_1-вкладка-«кабинет»-профиль-быстрые-ссылки-и-центр-ссылок" aria-label="Permalink to &quot;1. Вкладка «Кабинет»: Профиль, быстрые ссылки и центр ссылок&quot;">​</a></h2><p>Вкладка <strong>«Кабинет»</strong> служит командным центром маркетолога и отражает персональные показатели активности.</p><div class="craft-window-frame" data-title="Партнёрский кабинет амбассадора"><div style="padding:1.25rem;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.75rem;flex-wrap:wrap;gap:0.5rem;"><div><strong>Партнёрский статус:</strong> <span style="color:#3b82f6;font-weight:600;">Мастер (30%)</span></div><span style="opacity:0.85;">[ Списать бонусы ]</span></div><div style="margin-bottom:1rem;"><div style="font-size:0.9em;margin-bottom:0.25rem;opacity:0.85;">Прогресс до ранга «Легенда»: 24/50 продаж (48%)</div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:48%;background:#10b981;"></div></div></div><table class="craft-matrix-table" style="margin:0;text-align:center;"><thead><tr><th style="width:33%;text-align:center;">Переходы по ссылкам</th><th style="width:33%;text-align:center;">Подтверждённые покупки</th><th style="width:34%;text-align:center;">Доступно к выводу</th></tr></thead><tbody><tr><td><strong>1 420</strong></td><td><strong>24</strong></td><td><strong style="color:#10b981;">18 600,00 ₽</strong></td></tr></tbody></table></div></div><h3 id="персональныи-профиль-и-лестница-вознаграждении" tabindex="-1">Персональный профиль и лестница вознаграждений <a class="header-anchor" href="#персональныи-профиль-и-лестница-вознаграждении" aria-label="Permalink to &quot;Персональный профиль и лестница вознаграждений&quot;">​</a></h3><p>ОмниКрафт ЕРП поощряет активность практикующих мастеров прозрачной системой рангов:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ранг партнера</th><th style="text-align:center;">Процент комиссии</th><th style="text-align:center;">Требуемый объем продаж</th><th style="text-align:left;">Возможности ранга</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Партнёр</strong></td><td style="text-align:center;"><strong>20%</strong></td><td style="text-align:center;">Базовый уровень (от 0 продаж)</td><td style="text-align:left;">Неограниченная генерация ссылок, QR-коды на чеках, вывод рублей от 1 000 ₽.</td></tr><tr><td style="text-align:left;"><strong>Мастер</strong></td><td style="text-align:center;"><strong>30%</strong></td><td style="text-align:center;">От 10 продаж за последние 30 дней</td><td style="text-align:left;">Повышенная ставка вознаграждения, приоритетная обработка заявок на вывод средств.</td></tr><tr><td style="text-align:left;"><strong>Легенда</strong></td><td style="text-align:center;"><strong>50%</strong></td><td style="text-align:center;">От 50 продаж за последние 30 дней</td><td style="text-align:left;">Максимальная партнерская доля с каждого чека привлеченных пользователей.</td></tr></tbody></table><p>Под карточкой профиля расположен счетчик доступного баланса. Нажатием кнопки <strong>«Списать бонусы»</strong> открывается окно, в котором вы можете:</p><ol><li>Оформить заявку на вывод накопленных рублей на банковский счет;</li><li>Направить вознаграждение на продление стандартной подписки;</li><li>Оплатить бессрочный переход на профессиональный тариф «ПРО» без расхода личных денег.</li></ol><h3 id="генератор-быстрых-ссылок" tabindex="-1">Генератор быстрых ссылок <a class="header-anchor" href="#генератор-быстрых-ссылок" aria-label="Permalink to &quot;Генератор быстрых ссылок&quot;">​</a></h3><p>Если вам необходимо отправить ссылку коллеге в личном сообщении или быстро упомянуть калькулятор в комментарии, нет необходимости создавать отдельную рекламную кампанию.</p><p>В блоке <strong>«Быстрая ссылка»</strong> достаточно заполнить три поля:</p><ul><li><strong>Название ссылки:</strong> понятная краткая метка для себя (например, <em>«Совет в чате кожевников»</em>);</li><li><strong>Целевая страница:</strong> выберите нужный раздел из каталога: <ul><li><em>Главная страница</em> (<code>/</code>);</li><li><em>Калькулятор себестоимости изделий</em> (<code>/calculator</code>);</li><li><em>Тарифы и цены</em> (<code>/pricing</code>);</li><li><em>О программе</em> (<code>/software</code>);</li><li><em>База знаний и статьи</em> (<code>/blog</code>);</li><li><em>Демонстрационная версия</em> (<code>/demo</code>);</li><li><em>Произвольный адрес</em> (любая прямая страница официального сайта);</li></ul></li><li><strong>Метка кампании и примечание:</strong> необязательные параметры для дополнительной группировки.</li></ul><p>Нажмите синюю кнопку <strong>«Создать ссылку»</strong>: система мгновенно нормализует адрес, добавит персональный идентификатор партнера и выведет готовую ссылку с кнопкой копирования в буфер обмена.</p><h3 id="единыи-центр-всех-ссылок-реестр" tabindex="-1">Единый центр всех ссылок (Реестр) <a class="header-anchor" href="#единыи-центр-всех-ссылок-реестр" aria-label="Permalink to &quot;Единый центр всех ссылок (Реестр)&quot;">​</a></h3><p>Ниже на экране расположен полный список всех созданных ссылок с удобной фильтрацией:</p><ul><li><strong>«Все ссылки»</strong> — сводный перечень всех активных адресов;</li><li><strong>«Быстрые»</strong> — точечные ссылки, созданные для оперативных ответов;</li><li><strong>«Из кампаний»</strong> — ссылки, привязанные к конкретным рекламным проектам.</li></ul><p>В каждой строке реестра доступны три ключевых действия:</p><ol><li><strong>Копирование:</strong> сохранение адреса в буфер обмена в один клик;</li><li><strong>Просмотр QR-кода:</strong> открытие модального окна с крупным контрастным графическим кодом, удобным для считывания камерой телефона прямо с монитора;</li><li><strong>Привязка к кампании:</strong> любую быструю ссылку можно задним числом включить в состав нужного проекта;</li><li><strong>Удаление:</strong> неактуальные или ошибочные ссылки безопасно удаляются из реестра с подтверждением действия.</li></ol><h3 id="органическии-рост-qr-код-на-электронных-чеках-продаж" tabindex="-1">Органический рост: QR-код на электронных чеках продаж <a class="header-anchor" href="#органическии-рост-qr-код-на-электронных-чеках-продаж" aria-label="Permalink to &quot;Органический рост: QR-код на электронных чеках продаж&quot;">​</a></h3><p>Один из самых эффективных инструментов органического продвижения — распространение информации среди реальных покупателей вашей мастерской.</p><p>Включите переключатель <strong>«Размещать QR-код на чеках»</strong>:</p><ul><li>В модуле «Продажи» при оформлении розничного заказа программа автоматически добавит в нижнюю часть электронного чека аккуратный графический блок с вашим кодом;</li><li>Покупатель сканирует код со смартфона, переходит на сайт и знакомится с системой;</li><li>Если покупатель решит внедрить программу в собственном бизнесе, система навсегда закрепит его за вашим партнерским профилем.</li></ul><p>В правой части карточки доступен живой предпросмотр того, как блок чека выглядит на бумаге или экране смартфона.</p><hr><h2 id="_2-вкладка-«источники»-подбор-площадок-с-ии-и-база-контактов" tabindex="-1">2. Вкладка «Источники»: Подбор площадок с ИИ и база контактов <a class="header-anchor" href="#_2-вкладка-«источники»-подбор-площадок-с-ии-и-база-контактов" aria-label="Permalink to &quot;2. Вкладка «Источники»: Подбор площадок с ИИ и база контактов&quot;">​</a></h2><p>Чтобы реклама приносила результат, необходимо обращаться к аудитории, которой действительно нужно ваше предложение. Вкладка <strong>«Источники»</strong> помогает находить и систематизировать каналы продвижения.</p><div class="craft-window-frame" data-title="Подбор площадок и библиотека источников"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:55%;">Чат-стратег подбора площадок</th><th style="width:45%;">Библиотека источников и кандидаты</th></tr></thead><tbody><tr><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg></span><div><strong>Поисковый запрос:</strong> «Где найти мастеров по ремонту обуви?»</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="9" y1="9" x2="15" y2="9"></line><line x1="9" y1="13" x2="15" y2="13"></line></svg></span><div><strong>Карточка площадки:</strong> Обувной отраслевой форум.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Параметры:</strong> Аудитория 12 000 чел., кулдаун 14 дней.</div></li></ul></td><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle></svg></span><div><strong>Клуб кожевников:</strong> 3 кампании (2 активные).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg></span><div><strong>Чат столяров:</strong> 1 активная кампания.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polygon points="23 7 16 12 23 17 23 7"></polygon><rect x="1" y="5" width="15" height="14" rx="2" ry="2"></rect></svg></span><div><strong>Канал «Мастер»:</strong> Готов к запуску (0 кампаний).</div></li></ul></td></tr></tbody></table></div><h3 id="диалоговыи-ии-стратег-подбора-площадок" tabindex="-1">Диалоговый ИИ-стратег подбора площадок <a class="header-anchor" href="#диалоговыи-ии-стратег-подбора-площадок" aria-label="Permalink to &quot;Диалоговый ИИ-стратег подбора площадок&quot;">​</a></h3><p>Встроенный помощник работает на базе централизованного ядра искусственного интеллекта программы (<code>core.ai</code> с прямым персональным ключом доступа).</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="m4.93 4.93 4.24 4.24"></path><path d="m14.83 9.17 4.24-4.24"></path><path d="m14.83 14.83 4.24 4.24"></path><path d="m9.17 14.83-4.24 4.24"></path></svg></span><span><strong>Точный запрос под профиль ремесла:</strong> напишите ассистенту задачу на естественном русском языке: <em>«Где найти кожевников и изготовителей ремней для демонстрации калькулятора расхода кожи?»</em>.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg></span><span><strong>Структурированные карточки площадок:</strong> в ответ нейросеть вернет не просто ссылки, а готовые паспорта ресурсов с оценкой аудитории, правил размещения и рекомендуемой периодичности публикаций.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 11 12 14 22 4"></polyline><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"></path></svg></span><span><strong>Пакетный отбор кандидатов:</strong> отмечайте удачные варианты кнопкой <strong>«Выбрать»</strong> — карточки соберутся в верхнюю корзину, откуда вы перенесёте их в постоянную библиотеку одним нажатием кнопки.</span></li></ul><h3 id="анатомия-карточки-источника" tabindex="-1">Анатомия карточки источника <a class="header-anchor" href="#анатомия-карточки-источника" aria-label="Permalink to &quot;Анатомия карточки источника&quot;">​</a></h3><p>Каждая площадка в системе классифицируется по шести базовым типам:</p><ul><li><strong>Сообщество:</strong> группы в социальных сетях, каналы и чаты мастеров;</li><li><strong>Экспертная статья:</strong> блоги, публикации на отраслевых порталах и профильных сайтах;</li><li><strong>Форум:</strong> традиционные дискуссионные площадки с ветками обсуждений;</li><li><strong>Видео:</strong> видеохостинги, обзоры оборудования и видеоуроки;</li><li><strong>Реклама:</strong> платные баннеры, рекламные сети и промо-посевы;</li><li><strong>Другое:</strong> локальные выставки, ярмарки мастеров и очные встречи.</li></ul><p>Помимо типа, карточка хранит портрет целевой аудитории, правила модерации (чтобы избежать бана за спам), предпочтительный тон общения и <strong>период повторной публикации (кулдаун)</strong> в днях.</p><h3 id="пользовательская-база-проверенных-ресурсов-гибкая-настроика-параметров" tabindex="-1">Пользовательская база проверенных ресурсов (гибкая настройка параметров) <a class="header-anchor" href="#пользовательская-база-проверенных-ресурсов-гибкая-настроика-параметров" aria-label="Permalink to &quot;Пользовательская база проверенных ресурсов (гибкая настройка параметров)&quot;">​</a></h3><p>В программе нет навязанных сторонних каталогов. База формируется исключительно вами:</p><ul><li>Любую площадку можно отредактировать, дополнить контактами администратора или заархивировать;</li><li>В списке отображается счетчик активных кампаний (например, <em>«Клуб кожевников: 3 кампании, 2 активные»</em>);</li><li>Вся работа с базой доступна <strong>в полностью ручном режиме</strong> — если у вас не настроен ключ нейросети, вы вносите площадки через стандартную кнопку <strong>«Добавить источник»</strong>.</li></ul><hr><h2 id="_3-вкладка-«кампании»-связки-с-площадками-контент-и-публикации" tabindex="-1">3. Вкладка «Кампании»: Связки с площадками, контент и публикации <a class="header-anchor" href="#_3-вкладка-«кампании»-связки-с-площадками-контент-и-публикации" aria-label="Permalink to &quot;3. Вкладка «Кампании»: Связки с площадками, контент и публикации&quot;">​</a></h2><p>Вкладка <strong>«Кампании»</strong> объединяет все элементы маркетинга в единый технологический процесс: от замысла до контроля отдачи.</p><div class="craft-window-frame" data-title="Управление рекламной кампанией: «Осенний расчёт 2026»"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:55%;">Параметры кампании и креативы</th><th style="width:45%;">Участия площадок и размещения</th></tr></thead><tbody><tr><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path><path d="M2 12h20"></path></svg></span><div><strong>Целевая страница:</strong> <code>/calculator</code> (Теги: кожа, расчёт).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Статус и срок:</strong> Активна (до 30.11.2026).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg></span><div><strong>Тексты публикаций:</strong> Вариант 1 (Форум), Вариант 2 (Пост для соцсетей).</div></li></ul></td><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Форум кожевников:</strong> Органика · [ Опубликовано ].</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg></span><div><strong>Реферальная ссылка:</strong> <code>...?ref=INV-A1B2...</code></div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Следующий шаг:</strong> Проверка переходов через 3 дня.</div></li></ul></td></tr></tbody></table></div><h3 id="жизненныи-цикл-рекламнои-кампании" tabindex="-1">Жизненный цикл рекламной кампании <a class="header-anchor" href="#жизненныи-цикл-рекламнои-кампании" aria-label="Permalink to &quot;Жизненный цикл рекламной кампании&quot;">​</a></h3><p>Кампания создается под конкретную задачу мастера: продвижение нового набора инструментов, презентация обучающего курса или запуск калькулятора себестоимости.</p><p>Процесс строится по понятным шагам:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Шаг 1: Создание проекта.</strong> Нажмите <strong>«Новая кампания»</strong>, укажите понятное название, выберите продвигаемую страницу, задайте период проведения и добавьте тематические теги для аналитики.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><line x1="19" y1="8" x2="19" y2="14"></line><line x1="22" y1="11" x2="16" y2="11"></line></svg></span><span><strong>Шаг 2: Добавление площадок.</strong> Подключите к кампании проверенные источники из своей библиотеки. Для каждого размещения выберите режим (<em>«Органика»</em> или <em>«Платная»</em> с фиксацией выделенного бюджета).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg></span><span><strong>Шаг 3: Автоматическое рождение ссылки.</strong> При добавлении площадки система самостоятельно формирует точную пару «Кампания × Площадка» с уникальными метками источника. Метки подставляются строго кодом программы, исключая человеческие ошибки.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg></span><span><strong>Шаг 4: Подготовка публикации.</strong> Сформируйте текст с учетом специфики ресурса (экспертный совет для форума, краткий пост для соцсети, подробная статья для блога) или напишите черновик вручную.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Шаг 5: Публикация и контроль статуса.</strong> Разместите материал и переведите статус участия в <code>Опубликовано</code>. Программа запустит таймер следующего действия.</span></li></ul><h3 id="статусы-участия-площадки" tabindex="-1">Статусы участия площадки <a class="header-anchor" href="#статусы-участия-площадки" aria-label="Permalink to &quot;Статусы участия площадки&quot;">​</a></h3><p>Каждое размещение проходит через четыре наглядных состояния:</p><ul><li><code>Кандидат</code> — площадка предварительно отобрана для участия, но договоренности еще не достигнуты;</li><li><code>В работе</code> — готовится текст публикации или согласуются условия с администрацией;</li><li><code>Опубликовано</code> — материал физически размещен на ресурсе, ссылка активна;</li><li><code>Завершено</code> — кампания на данной площадке завершена, результаты зафиксированы в аналитике.</li></ul><h3 id="гарантия-точности-ссылок-детерминированная-подстановка" tabindex="-1">Гарантия точности ссылок (Детерминированная подстановка) <a class="header-anchor" href="#гарантия-точности-ссылок-детерминированная-подстановка" aria-label="Permalink to &quot;Гарантия точности ссылок (Детерминированная подстановка)&quot;">​</a></h3>',60)),e("p",null,[t[2]||(t[2]=l("При создании текстов с помощью нейросети действует жесткое инженерное правило: искусственный интеллект оперирует исключительно шаблонными плейсхолдерами ",-1)),e("code",null,s(a.CAMPAIGN_LINK),1),t[3]||(t[3]=l(" и ",-1)),e("code",null,s(a.PRODUCT_NAME),1),t[4]||(t[4]=l(".",-1))]),t[6]||(t[6]=r('<p>Реальный адрес с реферальным кодом и метками площадки подставляет системный сервис программы непосредственно перед выводом текста на экран. Нейросеть физически не способна исказить или «потерять» партнерский идентификатор.</p><h3 id="автоматическии-планировщик-«следующии-шаг»" tabindex="-1">Автоматический планировщик «Следующий шаг» <a class="header-anchor" href="#автоматическии-планировщик-«следующии-шаг»" aria-label="Permalink to &quot;Автоматический планировщик «Следующий шаг»&quot;">​</a></h3><p>После перевода карточки в статус <code>Опубликовано</code> система рассчитывает план дальнейших действий:</p><ol><li><strong>Через 3 дня:</strong> напоминание о необходимости проверить первые переходы и регистрации в Аналитике;</li><li><strong>По истечении кулдауна площадки:</strong> напоминание о возможности опубликовать следующий полезный материал без риска нарушить правила сообщества.</li></ol><hr><h2 id="_4-вкладка-«аналитика»-окупаемость-воронка-конверсии-и-экспорт-отчетов" tabindex="-1">4. Вкладка «Аналитика»: Окупаемость, воронка конверсий и экспорт отчетов <a class="header-anchor" href="#_4-вкладка-«аналитика»-окупаемость-воронка-конверсии-и-экспорт-отчетов" aria-label="Permalink to &quot;4. Вкладка «Аналитика»: Окупаемость, воронка конверсий и экспорт отчетов&quot;">​</a></h2><p>Маркетинг без точных цифр превращается в пустую трату времени и денег. Вкладка <strong>«Аналитика»</strong> дает мастеру ясную картину отдачи от каждого вложенного рубля и каждого опубликованного поста.</p><table class="craft-matrix-table" style="text-align:center;"><thead><tr><th style="width:33%;text-align:center;">Переходы по ссылкам</th><th style="width:33%;text-align:center;">Регистрации</th><th style="width:34%;text-align:center;">Оформленные покупки</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>4 820</strong></td><td style="text-align:center;"><strong>380</strong></td><td style="text-align:center;"><strong>48</strong></td></tr><tr><td style="text-align:center;"><strong>Партнёрский доход:</strong><br><span style="color:#10b981;font-weight:600;">42 600 ₽</span></td><td style="text-align:center;"><strong>Рекламный бюджет:</strong><br>8 500 ₽</td><td style="text-align:center;"><strong>Стоимость привлечения:</strong><br>177 ₽</td></tr></tbody></table><h3 id="_7-специализированных-аналитических-срезов" tabindex="-1">7 специализированных аналитических срезов <a class="header-anchor" href="#_7-специализированных-аналитических-срезов" aria-label="Permalink to &quot;7 специализированных аналитических срезов&quot;">​</a></h3><p>В верхней части экрана расположен селектор отчетов, позволяющий взглянуть на данные под разными углами:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Отчет</th><th style="text-align:left;">Что показывает мастеру</th><th style="text-align:left;">Практическая польза для дела</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Воронка по кампаниям</strong></td><td style="text-align:left;">Поэтапный путь клиента: Площадки ➔ Переходы ➔ Регистрации ➔ Покупки ➔ Доход с конверсией каждого шага.</td><td style="text-align:left;">Показывает, где отсеиваются люди: на этапе перехода по ссылке или при оформлении заказа.</td></tr><tr><td style="text-align:left;"><strong>Сравнение площадок</strong></td><td style="text-align:left;">Сводная таблица по парам «площадка × кампания»: тип размещения, бюджет, переходы, продажи, итоговая выручка.</td><td style="text-align:left;">Выявляет самые продуктивные каналы и отсекает бесполезные траты бюджета.</td></tr><tr><td style="text-align:left;"><strong>Срез по типам площадок</strong></td><td style="text-align:left;">Агрегированные итоги по категориям: сообщества, статьи, форумы, видео, прямая реклама.</td><td style="text-align:left;">Помогает понять, какой формат продвижения лучше всего воспринимается вашей аудиторией.</td></tr><tr><td style="text-align:left;"><strong>Срез по тегам</strong></td><td style="text-align:left;">Группировка показателей по тематическим направлениям (например, <em>«кожа»</em>, <em>«столярка»</em>, <em>«распродажа»</em>).</td><td style="text-align:left;">Оценивает результативность продвижения отдельных товарных групп.</td></tr><tr><td style="text-align:left;"><strong>Экономика платных размещений</strong></td><td style="text-align:left;">Расчет стоимости перехода, стоимости регистрации, стоимости покупателя и чистой окупаемости.</td><td style="text-align:left;">Защищает от убыточной рекламы: наглядно показывает, окупается ли платный трафик.</td></tr><tr><td style="text-align:left;"><strong>Динамика во времени</strong></td><td style="text-align:left;">График переходов и продаж по дням за выбранный период (7 дней, 30 дней, за все время).</td><td style="text-align:left;">Показывает скорость затухания эффекта от публикаций и помогает планировать график выходов.</td></tr><tr><td style="text-align:left;"><strong>Сводка по страницам</strong></td><td style="text-align:left;">Сравнение отдачи от различных посадочных адресов (Главная, Калькулятор, Блог, Демо).</td><td style="text-align:left;">Демонстрирует, какая страница сайта лучше всего конвертирует посетителей в покупателей.</td></tr></tbody></table><h3 id="расчет-ключевых-показателеи-экономики" tabindex="-1">Расчет ключевых показателей экономики <a class="header-anchor" href="#расчет-ключевых-показателеи-экономики" aria-label="Permalink to &quot;Расчет ключевых показателей экономики&quot;">​</a></h3><p>Вся математика модуля прозрачна и рассчитывается по строгим формулам:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Экономика маркетинга</span><div class="formula-heading">Формулы эффективности рекламных каналов</div></div><div class="formula-equation-box"><div class="math-calc-stack"><div class="math-calc-row"><span class="math-calc-label">Конверсия в покупку:</span><span class="math-calc-expr">(Число покупок ÷ Число переходов) × 100%</span></div><div class="math-calc-row"><span class="math-calc-label">Стоимость привлечения покупателя:</span><span class="math-calc-expr">Израсходованный бюджет ÷ Число покупок</span></div><div class="math-calc-row"><span class="math-calc-label">Чистая окупаемость рекламы:</span><span class="math-calc-expr">((Выручка − Затраты на рекламу) ÷ Затраты на рекламу) × 100%</span></div></div></div><div class="formula-card-bottom"><p>Метрики вычисляются программой автоматически на основе данных трекинга ссылок и зафиксированных расходов.</p></div></div><div class="info custom-block"><p class="custom-block-title">Реальная математика ремесла</p><p>Если на рекламу в сообществе кожевников потрачено 3 000 рублей, получено 200 переходов и 6 продаж лицензий с партнерским доходом 4 800 рублей, то стоимость привлечения одного клиента составила 500 рублей, а чистая окупаемость вложений достигла 60%.</p></div><h3 id="экспорт-данных-и-автономная-работа" tabindex="-1">Экспорт данных и автономная работа <a class="header-anchor" href="#экспорт-данных-и-автономная-работа" aria-label="Permalink to &quot;Экспорт данных и автономная работа&quot;">​</a></h3><ul><li><strong>Кнопка «Экспорт в CSV»:</strong> формирует файл таблицы с кодировкой UTF-8 BOM, который корректно и без искажения кириллицы открывается в любых табличных редакторах (Excel, МойОфис, LibreOffice);</li><li><strong>Кнопка «Скопировать отчёт»:</strong> сохраняет структурированную текстовую сводку в буфер обмена для быстрой отправки в личные заметки или мессенджер;</li><li><strong>Автономность:</strong> если интернет временно недоступен, модуль автоматически строит все отчеты по локальным снимкам метрик с предупреждающим значком об офлайн-режиме.</li></ul><hr><h2 id="_5-внешние-цифровые-ассистенты-и-протокол-контекста-моделеи" tabindex="-1">5. Внешние цифровые ассистенты и протокол контекста моделей <a class="header-anchor" href="#_5-внешние-цифровые-ассистенты-и-протокол-контекста-моделеи" aria-label="Permalink to &quot;5. Внешние цифровые ассистенты и протокол контекста моделей&quot;">​</a></h2><p>Модуль «Амбассадор» спроектирован с учетом современных технологий автоматизации. В него встроена поддержка открытого <strong>протокола контекста моделей</strong>.</p><p>Это позволяет подключать к ведению маркетинга внешних автономных ИИ-ассистентов (например, в средах разработки или локальных агентах):</p><ul><li><strong>Реестр безопасных инструментов:</strong> внешнему помощнику доступны строго регламентированные функции: <ul><li><code>list_campaigns</code> — получение списка активных кампаний;</li><li><code>get_stats</code> — чтение сводных метрик эффективности;</li><li><code>create_link</code> — генерация целевой ссылки с параметрами;</li><li><code>generate_content</code> — запрос на подготовку текста под формат площадки;</li><li><code>mark_published</code> — фиксация факта размещения материала;</li><li><code>export_task</code> — выгрузка полного контекста задачи.</li></ul></li><li><strong>Уровни контроля и подтверждение человеком:</strong><ul><li><em>Черновик:</em> ассистент только готовит варианты текста и ожидает проверки мастера;</li><li><em>Полуавтомат:</em> автоматическое размещение с принудительной остановкой при обнаружении капчи или двухфакторного подтверждения входа;</li><li><em>Автопилот:</em> доступен исключительно для доверенных внутренних каналов.</li></ul></li><li><strong>Журнал аудита:</strong> каждое обращение внешнего агента к базе данных фиксируется в служебном журнале с точным временем отклика и перечнем переданных параметров.</li></ul><hr><h2 id="_6-партнерская-программа-честная-экономика-и-использование-баланса" tabindex="-1">6. Партнерская программа: честная экономика и использование баланса <a class="header-anchor" href="#_6-партнерская-программа-честная-экономика-и-использование-баланса" aria-label="Permalink to &quot;6. Партнерская программа: честная экономика и использование баланса&quot;">​</a></h2><p>Партнерская программа ОмниКрафт ЕРП построена на принципах взаимного уважения и долгосрочного сотрудничества.</p><h3 id="пожизненное-закрепление-бессрочныи-доступ" tabindex="-1">Пожизненное закрепление (бессрочный доступ) <a class="header-anchor" href="#пожизненное-закрепление-бессрочныи-доступ" aria-label="Permalink to &quot;Пожизненное закрепление (бессрочный доступ)&quot;">​</a></h3><p>Когда коллега регистрируется по вашей реферальной ссылке или сканирует QR-код с выданного вами товарного чека, система <strong>навсегда закрепляет пользователя за вашим профилем</strong>:</p><ul><li>вы получаете процент не только с его первой оплаты, но и со всех последующих продлений лицензии;</li><li>Если привлеченный мастер докупает специализированные отраслевые модули в Маркетплейсе, партнерская комиссия начисляется и на эти покупки;</li><li>Начисления производятся в реальных рублях на ваш баланс внутри программы.</li></ul><h3 id="использование-заработанных-средств" tabindex="-1">Использование заработанных средств <a class="header-anchor" href="#использование-заработанных-средств" aria-label="Permalink to &quot;Использование заработанных средств&quot;">​</a></h3><p>Накопленный баланс не сгорает со временем, вы распоряжаетесь им по собственному усмотрению:</p><table class="craft-matrix-table"><thead><tr><th style="width:40%;">Направление использования</th><th style="width:60%;">Условия и механизм списания</th></tr></thead><tbody><tr><td><strong>Вывод на банковский счёт</strong></td><td>Прямой перевод на банковскую карту или по реквизитам счёта (вывод от 1 000 ₽).</td></tr><tr><td><strong>Продление лицензии</strong></td><td>Автоматическое списание накопленных бонусов за тариф «Стандарт».</td></tr><tr><td><strong>Бессрочный переход на ПРО</strong></td><td>Полная разблокировка мультипространств без затрат денег за счёт бонусов.</td></tr><tr><td><strong>Покупка модулей</strong></td><td>Оплата отраслевых инструментов и шаблонов в Маркетплейсе с партнёрского баланса.</td></tr></tbody></table><hr><h2 id="вопросы-и-ответы-мастера" tabindex="-1">Вопросы и ответы мастера <a class="header-anchor" href="#вопросы-и-ответы-мастера" aria-label="Permalink to &quot;Вопросы и ответы мастера&quot;">​</a></h2><h3 id="обязательно-ли-подключать-ключ-неиросети-для-работы-с-модулем" tabindex="-1">Обязательно ли подключать ключ нейросети для работы с модулем? <a class="header-anchor" href="#обязательно-ли-подключать-ключ-неиросети-для-работы-с-модулем" aria-label="Permalink to &quot;Обязательно ли подключать ключ нейросети для работы с модулем?&quot;">​</a></h3><p>Нет, совершенно необязательно. Модуль спроектирован так, что весь базовый функционал — ручное создание ссылок, ведение базы площадок, учет рекламных расходов, печать QR-кодов на чеках, воронка конверсий и аналитика — доступен в полном объеме без настройки нейросетей. Искусственный интеллект является лишь удобным ускорителем рутины.</p><h3 id="как-начисляется-вознаграждение-если-клиент-перешел-по-ссылке-но-купил-программу-позже" tabindex="-1">Как начисляется вознаграждение, если клиент перешел по ссылке, но купил программу позже? <a class="header-anchor" href="#как-начисляется-вознаграждение-если-клиент-перешел-по-ссылке-но-купил-программу-позже" aria-label="Permalink to &quot;Как начисляется вознаграждение, если клиент перешел по ссылке, но купил программу позже?&quot;">​</a></h3><p>При первом переходе по вашей ссылке в браузере пользователя сохраняется специальная метка. Даже если мастер оплатит лицензию спустя несколько дней или недель, сервер биллинга корректно свяжет платеж с вашим кодом амбассадора и зачислит комиссию на баланс.</p><h3 id="что-произоидет-с-ссылками-и-статистикои-при-смене-рабочего-пространства" tabindex="-1">Что произойдет с ссылками и статистикой при смене рабочего пространства? <a class="header-anchor" href="#что-произоидет-с-ссылками-и-статистикои-при-смене-рабочего-пространства" aria-label="Permalink to &quot;Что произойдет с ссылками и статистикой при смене рабочего пространства?&quot;">​</a></h3><p>Ничего не пропадет. Модуль «Амбассадор» является сквозным глобальным инструментом. Его база данных хранится отдельно от производственных цехов. Можно свободно менять направления деятельности, очищать тестовые заказы или создавать новые мастерские — все ссылки, кампании и накопленные рубли останутся нетронутыми.</p><h3 id="как-избежать-блокировок-за-спам-при-размещении-ссылок-на-форумах" tabindex="-1">Как избежать блокировок за спам при размещении ссылок на форумах? <a class="header-anchor" href="#как-избежать-блокировок-за-спам-при-размещении-ссылок-на-форумах" aria-label="Permalink to &quot;Как избежать блокировок за спам при размещении ссылок на форумах?&quot;">​</a></h3><p>Главное правило профессионального продвижения — приносить пользу сообществу. Публикуйте ссылки только в контексте реального ответа на вопрос коллеги (например, делитесь готовым расчетом себестоимости сложного изделия или шаблоном технологической карты). В карточке каждой площадки обязательно фиксируйте установленный интервал (кулдаун) и следуйте напоминаниям планировщика «Следующий шаг».</p>',41))])}const k=o(g,[["render",u]]);export{m as __pageData,k as default};
